// Khởi tạo các biến nếu chưa có
let metalCount = flow.get('metalCount') || 0;
let nonMetalCount = flow.get('nonMetalCount') || 0;
let totalCount = flow.get('totalCount') || 0;
let lastState = context.get('lastState') || false;

// 0. Khởi tạo dữ liệu hiển thị ban đầu (Startup)
if (msg.topic === "init") {
    return [
        { payload: metalCount, topic: "SP Kim loại" },
        { payload: nonMetalCount, topic: "SP Phi kim" },
        { payload: totalCount, topic: "Tổng sản phẩm" },
        null
    ];
}

// 1. Xử lý nút Reset (đã qua hộp thoại xác nhận)
if (msg.topic === "reset" || msg.payload === "reset" || msg.payload === "Xác nhận đặt lại") {
    metalCount = 0;
    nonMetalCount = 0;
    totalCount = 0;
    flow.set('metalCount', 0);
    flow.set('nonMetalCount', 0);
    flow.set('totalCount', 0);
    context.set('lastState', false);
    return [
        { payload: 0, topic: "SP Kim loại" },         // Out 1: SP Kim loại
        { payload: 0, topic: "SP Phi kim" },          // Out 2: SP Phi kim
        { payload: 0, topic: "Tổng sản phẩm" },       // Out 3: Tổng sản phẩm
        null                                          // Out 4: Kích hoạt Solenoid
    ];
}

// 2. Xử lý nút Giả lập SP Phi kim (Demo)
if (msg.topic === "non_metal" || msg.payload === "non_metal") {
    nonMetalCount += 1;
    totalCount += 1;
    flow.set('nonMetalCount', nonMetalCount);
    flow.set('totalCount', totalCount);
    return [
        null,
        { payload: nonMetalCount, topic: "SP Phi kim" },
        { payload: totalCount, topic: "Tổng sản phẩm" },
        null
    ];
}

// 3. Xử lý tín hiệu cảm biến IN1 hoặc nút test kim loại
let isMetal = false;
if (Array.isArray(msg.payload)) {
    isMetal = Boolean(msg.payload[0]);
} else if (typeof msg.payload === "boolean") {
    isMetal = msg.payload;
}

// Phát hiện sườn lên (Rising Edge: false -> true)
if (isMetal && !lastState) {
    context.set('lastState', true);
    metalCount += 1;
    totalCount += 1;
    flow.set('metalCount', metalCount);
    flow.set('totalCount', totalCount);

    return [
        { payload: metalCount, topic: "SP Kim loại" },
        null,
        { payload: totalCount, topic: "Tổng sản phẩm" },
        { payload: [true], topic: "trigger" }      // Out 4: Kích hoạt Solenoid
    ];
} else if (!isMetal) {
    context.set('lastState', false);
}

return null;

// Xử lý trạng thái kết nối Modbus
let status = msg.status || {};
let fill = status.fill || '';
let text = (status.text || '').toLowerCase();

// Hỗ trợ kiểm thử từ nút giả lập trong Tab Bảo trì
if (msg.topic === 'test_modbus_error') {
    flow.set('modbusOnline', false);
    return {
        payload: {
            isError: true,
            title: 'LỖI KẾT NỐI MODBUS',
            detail: 'Mất kết nối Modbus / Cáp lỏng (Giả lập kiểm thử)'
        }
    };
} else if (msg.topic === 'test_modbus_ok' || msg.topic === 'init') {
    flow.set('modbusOnline', true);
    return {
        payload: {
            isError: false,
            title: 'MODBUS RTU: TRUYỀN THÔNG ỔN ĐỊNH',
            detail: '127.0.0.1:502 (Slave ID: 1)'
        }
    };
}

let isError = (fill === 'red') || 
              text.includes('error') || 
              text.includes('timeout') || 
              text.includes('disconnected') || 
              text.includes('fail') || 
              text.includes('lỗi');

let isNormal = (fill === 'green') || (fill === 'yellow') || 
               text.includes('active') || text.includes('reading') || text.includes('connected');

if (isError) {
    flow.set('modbusOnline', false);
} else if (isNormal) {
    flow.set('modbusOnline', true);
}

let online = flow.get('modbusOnline');
if (online === undefined) online = true;

return {
    payload: {
        isError: !online,
        title: !online ? 'LỖI KẾT NỐI MODBUS' : 'MODBUS RTU: TRUYỀN THÔNG ỔN ĐỊNH',
        detail: status.text || (!online ? 'Mất tín hiệu truyền thông / Cáp lỏng / Mất điện' : '127.0.0.1:502 (Slave ID: 1)')
    }
};

// Thu thập dữ liệu báo cáo thống kê cuối ca
let metalCount = flow.get('metalCount') || 0;
let nonMetalCount = flow.get('nonMetalCount') || 0;
let totalCount = flow.get('totalCount') || 0;

let now = new Date();
let pad = (n) => n < 10 ? '0' + n : n;
let dateStr = pad(now.getDate()) + '/' + pad(now.getMonth() + 1) + '/' + now.getFullYear();
let timeStr = pad(now.getHours()) + ':' + pad(now.getMinutes()) + ':' + pad(now.getSeconds());

let metalPercent = totalCount > 0 ? ((metalCount / totalCount) * 100).toFixed(1) + '%' : '0%';
let nonMetalPercent = totalCount > 0 ? ((nonMetalCount / totalCount) * 100).toFixed(1) + '%' : '0%';

let filename = 'Bao_cao_san_luong_' + now.getFullYear() + pad(now.getMonth() + 1) + pad(now.getDate()) + '_' + pad(now.getHours()) + pad(now.getMinutes()) + '.csv';
msg.filename = filename;

// Chuẩn bị mảng bản ghi xuất CSV
msg.payload = [
    {
        "Ngày báo cáo": dateStr,
        "Thời gian": timeStr,
        "SP Kim loại (chiếc)": metalCount,
        "Tỉ lệ Kim loại": metalPercent,
        "SP Phi kim (chiếc)": nonMetalCount,
        "Tỉ lệ Phi kim": nonMetalPercent,
        "Tổng sản lượng (chiếc)": totalCount,
        "Trạng thái ca": "Hoàn tất thống kê",
        "Ghi chú": "Hệ thống phân loại sản phẩm SCADA/HMI BTL MMT"
    }
];

return msg;

// Tính toán tốc độ sản xuất (Số sản phẩm / phút - PPM)
let now = Date.now();
let windowMs = 60000; // Cửa sổ trượt 60 giây
let history = context.get('history') || [];
let lastCountTime = context.get('lastCountTime') || 0;

// Cập nhật trạng thái chạy của băng chuyền
if (msg.topic === "conveyor_state") {
    flow.set('isConveyorRunning', Boolean(msg.payload));
}

let isRunning = flow.get('isConveyorRunning');
if (isRunning === false) {
    history = [];
    context.set('history', history);
    flow.set('currentPPM', 0);
    return { payload: 0, topic: "Tốc độ sản xuất" };
}

// Nếu nhận tín hiệu đếm sản phẩm mới từ bộ đếm
if (msg.topic === "SP Kim loại" || msg.topic === "SP Phi kim" || msg.topic === "count_trigger") {
    history.push(now);
    lastCountTime = now;
    context.set('lastCountTime', lastCountTime);
}

// Lọc các mốc thời gian ngoài cửa sổ 60s
history = history.filter(t => (now - t) <= windowMs);
context.set('history', history);

let ppm = 0;
if (history.length > 0) {
    if (history.length >= 2) {
        let spanSec = (history[history.length - 1] - history[0]) / 1000;
        if (spanSec >= 2) {
            let instantPpm = Math.round((history.length / spanSec) * 60);
            ppm = Math.min(Math.max(history.length, instantPpm), 120);
        } else {
            ppm = history.length;
        }
    } else {
        ppm = history.length;
    }

    // Nếu quá 12 giây không có sản phẩm mới qua cảm biến, giảm tốc độ
    if (now - lastCountTime > 12000) {
        ppm = Math.round(ppm * 0.4);
    }
}

flow.set('currentPPM', ppm);

return {
    payload: ppm,
    topic: "Tốc độ sản xuất"
};

// Xử lý lưu trữ bền vững (Persistent Storage & Database Logging)
let metal = flow.get('metalCount') || 0;
let nonMetal = flow.get('nonMetalCount') || 0;
let total = flow.get('totalCount') || 0;
let ppm = flow.get('currentPPM') || 0;

let now = new Date();
let timestamp = now.toISOString();
let timeVN = now.toLocaleString('vi-VN');

// 1. Trạng thái JSON để ghi đè (Khôi phục khi bật máy/mất điện)
let stateObj = {
    metalCount: metal,
    nonMetalCount: nonMetal,
    totalCount: total,
    currentPPM: ppm,
    lastUpdated: timeVN
};

// 2. Dòng nhật ký Audit Log (Ghi nối tiếp)
let logLine = timestamp + " | METAL=" + metal + " | NON_METAL=" + nonMetal + " | TOTAL=" + total + " | PPM=" + ppm + "\r\n";

// 3. Câu lệnh SQL (MySQL) & InfluxDB Line Protocol
let sql = "INSERT INTO production_logs (logged_at, metal, non_metal, total, ppm) VALUES ('" + timestamp + "', " + metal + ", " + nonMetal + ", " + total + ", " + ppm + ");";
let influx = "production_stats,line=conveyor_01 metal=" + metal + "i,non_metal=" + nonMetal + "i,total=" + total + "i,ppm=" + ppm + "i " + (now.getTime() * 1000000);

return [
    { payload: JSON.stringify(stateObj, null, 2), filename: "C:/Users/Acer/OneDrive/Desktop/BTLMMT/data/conveyor_state.json" },
    { payload: logLine, filename: "C:/Users/Acer/OneDrive/Desktop/BTLMMT/data/production_audit.log" },
    { payload: { sql: sql, influx: influx, state: stateObj } }
];

// Khôi phục bộ đếm từ file sau sự cố mất điện / khởi động lại
try {
    let saved = (typeof msg.payload === 'string') ? JSON.parse(msg.payload) : msg.payload;
    if (saved && (saved.metalCount !== undefined || saved.nonMetalCount !== undefined)) {
        let m = saved.metalCount || 0;
        let nm = saved.nonMetalCount || 0;
        let tot = saved.totalCount || (m + nm);

        flow.set('metalCount', m);
        flow.set('nonMetalCount', nm);
        flow.set('totalCount', tot);

        node.warn('Đã khôi phục thành công dữ liệu sản lượng từ ổ đĩa: ' + tot + ' SP');

        return [
            { payload: m, topic: "SP Kim loại" },
            { payload: nm, topic: "SP Phi kim" },
            { payload: tot, topic: "Tổng sản phẩm" }
        ];
    }
} catch (e) {
    node.error('Lỗi phân tích file trạng thái: ' + e.message);
}
return null;
